function useProfileSave(options?:{travelOnly?:boolean;onSaved?:()=>void}){
 const {setup,saved,setSaved,storage}=useStore(),nav=useNavigation<Nav>();
 const [saving,setSaving]=useState(false),[error,setError]=useState('');
 async function save(travel?:TravelProfile){
  if(saving)return;setSaving(true);setError('');
  try{const raw=await storage.getItem(KEY),fresh=readPreview(JSON.parse(raw??'null')),s=fresh.profile?fresh:saved,world=travel?completeTravelProfile(travel):s.profile?.travel;
   if(!s.profile&&!world)throw new Error('Pick at least three wishlist places first.');
   const profile=options?.travelOnly&&s.profile?{...s.profile,...(world?{travel:world}:{})}:{name:setup.name,avatar:setup.avatar,ageBand:setup.ageBand,...readProfileLocation(setup),...(world?{travel:world}:{})};
   const updated={...s,profile,...(s.profile?.ageBand!==profile.ageBand?{answers:{},completed:false,saved:[],reactions:{},daily:{...s.daily,active:null},visits:hideAllCityVisits(s.visits),photos:{...privatizeCityPhotos(s.photos),...(!s.profile?{activityStartedMonth:cityPhotoMonth(new Date())}:{})}}:{})};
   const next=s.profile?updated:enableLaunch(updated);await storage.setItem(KEY,JSON.stringify(next));setSaved(next);
   if(options?.onSaved)options.onSaved();else if(saved.profile)nav.popTo('Profile');else nav.reset({index:0,routes:[{name:'Main',params:{screen:'Home'}}]});
  }catch(e){setError((e as Error).message||'Couldn’t save. Please try again.');}finally{setSaving(false);}
 }
 return {save,saving,error};
}
