 return <NativeTravelSetup initial={setup.travel??saved.profile?.travel} onChange={travel=>setSetup(s=>({...s,travel}))} onComplete={profile.save} onBack={leave} busy={profile.saving} error={profile.error} editing={!!saved.profile} section={section} onOpenCities={()=>nav.push('TravelCityPicker',{section})} onOpenCity={cityId=>openPlacePicker(section,cityId)} onSectionChange={next=>{if(saved.profile)nav.setParams({section:next});else if(next==='wishlist')nav.push('TravelSetup',{section:next});else nav.goBack();}}/>;
