function PlayScreen({route,navigation}:NativeStackScreenProps<Root,'Play'>){const {saved,setSaved,ideas,setIdeas,now}=useStore(),profile=saved.profile??FALLBACK_PROFILE,index=Math.max(0,Math.min(route.params.index,2)),preparing=!!route.params.invite&&!!saved.launch?.preparation,questions=preparing?invitePreparationQuestions(saved):activeQuestions(saved.daily,profile.ageBand),q=questions[index],answer=preparing?saved.launch!.preparation!.answers[index]:saved.daily.active?.answers[q?.id]??'',usage=weeklyIdeas(ideas,now),idea=usage.revealed[q?.id],remaining=3-usage.used;const status=preparing?{kind:'ready' as const,remainingMs:0}:dailyStatus(saved.daily,now),finishing=useRef(false),focused=useIsFocused(),locked=!!saved.launch&&!preparing&&palFindingProgress(saved).eligible&&!palFindingProgress(saved).canPlay;useEffect(()=>{if(focused&&!finishing.current){if(locked)navigation.replace('LaunchUnlock');else if(status.kind!=='ready'||(!preparing&&!saved.daily.active))navigation.popTo('Main',{screen:'Home'});}},[status.kind,saved.daily.active,navigation,focused,preparing,locked]);if(!q||(!preparing&&!saved.daily.active)||status.kind!=='ready'||locked)return <Screen><ActivityIndicator color={BLUE}/></Screen>;const typingMatches=saved.launch?0:playAnswerCount(answer,q.id,profile.ageBand,saved.daily,saved.blocked,knownConnectionIds(saved.social,profile.ageBand,saved.blocked));
  function submit(){if(finishing.current||!questionChoices(q).some(c=>c.label===answer))return;if(preparing){try{const draft=answerInvitePreparation(saved,index,answer),next=index<2?submitInvitePreparation(draft,index):finishInvitePreparation(draft);if(index===2)finishing.current=true;setSaved(next);if(index<2)navigation.push('Play',{index:index+1,invite:true});else navigation.reset({index:1,routes:[{name:'Main'},{name:'LaunchUnlock'}]});}catch(e){Alert.alert('Your invite',(e as Error).message);}return;}if(index<2){try{const daily=submitDaily(saved.daily,q.id);setSaved(s=>({...s,daily}));navigation.push('Play',{index:index+1});}catch{navigation.popTo('Main',{screen:'Home'});}return;}const missing=saved.daily.active!.ids.findIndex(id=>!saved.daily.active!.answers[id]?.trim());if(missing>=0){navigation.replace('Play',{index:missing});return;}try{const next=saved.launch?finishLaunchPlay(saved):completeDemoPlay(saved);finishing.current=true;setSaved(next);navigation.reset({index:1,routes:[{name:'Main'},{name:saved.launch&&profile.ageBand==='10-12'?'LaunchReady':'Matching'}]});}catch{navigation.popTo('Main',{screen:'Home'});}}
  return <NativePerfectDayPlay questions={questions} index={index} answer={answer} answers={preparing?Object.fromEntries(questions.map((q,i)=>[q.id,saved.launch!.preparation!.answers[i]])):saved.daily.active?.answers??{}} onSelect={value=>setSaved(s=>preparing?answerInvitePreparation(s,index,value):({...s,daily:answerDaily(s.daily,q.id,value)}))} onNext={submit} finalLabel={preparing?'Make my postcard':profile.ageBand==='10-12'?'See my day':'Find my roamie'}/>;
}
