function ShareScreen(){const {saved}=useStore(),stats=worldStats(saved),items=worldPlaces(saved).filter(p=>p.uncovered).slice(0,2);return <Screen><Title>My little{`\n`}<Hand>world.</Hand></Title><View style={{flex:1,minHeight:150,maxHeight:310,flexDirection:'row',gap:16,paddingVertical:10}}>{items.length?items.map(item=><View key={item.country.id} style={{flex:1,alignItems:'center'}}><NativePlaceArt country={item.country}/><Copy small>{item.country.flag} {item.country.city}</Copy></View>):<View style={{flex:1,justifyContent:'center',alignItems:'center'}}><Ionicons name="globe-outline" size={92} color="#F1F5EB"/><Copy>Your first city is waiting.</Copy></View>}</View><Footer><CTA label="Send the invite" onPress={()=>{void Share.share({message:`I’ve uncovered ${stats.cities} cities and learned about ${stats.attractions} places in Kymzi’s demo. Answer 3. See where you land.`}).catch(()=>Alert.alert('Share unavailable','Try again from your device’s share menu.'));}}/><Copy small>City discoveries · Your collection</Copy></Footer></Screen>;}
function ProfileScreen(){return <NativeHeaderUnderlay><ProfileScreenContent/></NativeHeaderUnderlay>;}
function ProfileScreenContent(){const {saved,setSetup,now,clearLocalData}=useStore(),nav=useNavigation<Nav>(),launch=useLaunchActions(),editTravel=useTravelEditor(),p=saved.profile??FALLBACK_PROFILE;if(saved.launch)return <NativeLaunchProfile onTravel={()=>editTravel('visited')} travel={<><NativeTravelFootprints state={saved} onEdit={()=>editTravel('visited')}/><TravelWishlistBlock/></>} onInvite={()=>void launch.invite()} onFeed={()=>nav.popTo('Main',{screen:'Home'})} onClear={clearLocalData} onCircle={()=>nav.navigate('LaunchUnlock')} state={saved} now={now} onPal={peerId=>nav.navigate('Pal',{peerId})} onEdit={()=>{setSetup(createSetupProfile(p));nav.navigate('Setup');}} onTasks={()=>nav.popTo('Main',{screen:'Tasks'})} onCards={()=>nav.navigate('LaunchPostcards')} onPhotos={()=>nav.navigate('LaunchMoments')} onAbout={()=>nav.navigate('About')} onPreview={()=>nav.navigate('LaunchUnlock',{demo:true})} onSchedule={()=>nav.navigate('Schedule')}/>;
 return <NativeSimpleProfile state={saved} onTravel={()=>editTravel('visited')} onEdit={()=>{setSetup(createSetupProfile(p));nav.navigate('Setup');}} onClear={clearLocalData} travel={saved.profile?.travel?<><NativeTravelFootprints state={saved} onEdit={()=>editTravel('visited')}/><TravelWishlistBlock/></>:undefined} items={[
  {label:'My cities',icon:'globe-outline',onPress:()=>nav.popTo('Main',{screen:'Cities'})},
  {label:'My shared places',icon:'location-outline',onPress:()=>nav.navigate('CityPhotos')},
  {label:'Share places',icon:'add-outline',onPress:()=>nav.popTo('Main',{screen:'Tasks'})},
  ...(isAdult(p.ageBand)?[{label:'Visits',icon:'calendar-outline' as const,onPress:()=>nav.navigate('Visits')}]:[]),
  ...(saved.daily.lastCompletedAt?[{label:'Daily play time',icon:'time-outline' as const,onPress:()=>nav.navigate('Schedule')}]:[]),
  {label:'Settings',icon:'options-outline',onPress:()=>nav.navigate('Settings')},
 ]}/>;
}
function SettingsScreen(){const nav=useNavigation<Nav>();return <Screen><Row label="Invite an explorer" icon="share-outline" onPress={()=>nav.navigate('Share')}/><Row label="About Kymzi" icon="information-circle-outline" onPress={()=>nav.navigate('About')}/><Copy small>Saved on this device.</Copy></Screen>;}
function AboutScreen(){const {saved}=useStore(),nav=useNavigation<Nav>();if(saved.launch)return <NativeLaunchAbout onBack={()=>nav.popTo('Main',{screen:'Home'})}/>;return <Screen><Title>A little curiosity.{`\n`}<Hand>A bigger world.</Hand></Title><View>{([{icon:'happy-outline',text:'3 answers · 5 plays a day'},{icon:'compass-outline',text:`${WORLD_CATALOGUE.cities.toLocaleString('en')} cities · ${WORLD_CATALOGUE.places.toLocaleString('en')} places to explore`},{icon:'location-outline',text:'Hidden gems, shared by locals'},{icon:'chatbubble-outline',text:'City DMs · Photo after 3 matches'},{icon:'shield-checkmark-outline',text:'Anonymous city connections'}] as const).map(f=><View key={f.text} className="flex-row items-center gap-4 border-b border-line py-4"><Ionicons name={f.icon} size={23} color={BLUE}/><Text className="text-[18px] font-medium text-ink flex-1">{f.text}</Text></View>)}</View><Footer><Copy small>City presence and meetups are for adults only. Younger children explore privately; teen roamies stay within their age group.</Copy><Copy small>Fictional matches and illustrated place previews. Your chosen character is your public identity. Progress saved on this device. Connections stay anonymous. City boards, check-ins, notifications and meetups are local previews. No real announcement or invitation is sent.</Copy></Footer></Screen>;}
function useVisitChange(){const {saved,setSaved}=useStore();return (action:(state:PreviewState)=>CityVisitsState)=>{const visits=action(saved);setSaved(s=>({...s,visits}));return visits;};}
function VisitsScreen(){const {saved,now}=useStore(),nav=useNavigation<Nav>(),play=usePlay();if(!isAdult((saved.profile??FALLBACK_PROFILE).ageBand))return <Screen><Title>Visits are for adults.</Title></Screen>;return <NativeVisitsHome state={saved} now={now} onPlan={countryId=>nav.navigate('PlanVisit',{countryId})} onVisit={id=>nav.navigate('VisitDetail',{id})} onUpdates={()=>nav.navigate('CityUpdates')} onPlay={play} onMeet={id=>nav.navigate('CityMeetDetail',{id})}/>;}
function PlanVisitScreen({route,navigation}:NativeStackScreenProps<Root,'PlanVisit'>){const {saved,now}=useStore(),change=useVisitChange();if(!isAdult((saved.profile??FALLBACK_PROFILE).ageBand)||!worldPlaces(saved).some(p=>p.uncovered))return <Screen><Title>Discover a city first.</Title></Screen>;return <NativeVisitPlanner state={saved} now={now} initialCountry={route.params?.countryId} onPost={(id,from,to,time)=>{const result=change(s=>postCityVisit(s,id,from,to,time));navigation.replace('VisitDetail',{id:result.visits.find(v=>v.countryId===id&&v.ageBand===saved.profile?.ageBand&&v.status!=='cancelled')!.id});}}/>;}
function CityBoardScreen({route,navigation}:NativeStackScreenProps<Root,'CityBoard'>){const {saved,now}=useStore(),id=route.params.countryId;if(!canUseCityBoard(saved,id))return <Screen><Title>City board unavailable.</Title></Screen>;return <NativeCityBoard state={saved} now={now} id={id} onPlan={countryId=>navigation.navigate('PlanVisit',{countryId})} onVisit={id=>navigation.navigate('VisitDetail',{id})} onMeet={visitorId=>navigation.navigate('CityMeetPlan',{countryId:id,visitorId})} onUpdates={()=>navigation.navigate('CityUpdates')} onCheckIn={()=>navigation.navigate('SpotCheckIn',{countryId:id})} onSpot={spotId=>navigation.navigate('SpotPeople',{countryId:id,spotId})}/>;}
function VisitDetailScreen({route,navigation}:NativeStackScreenProps<Root,'VisitDetail'>){const {saved,now}=useStore(),change=useVisitChange(),visit=saved.visits.visits.find(v=>v.id===route.params.id&&v.ageBand===saved.profile?.ageBand);if(!visit||!canUseCityBoard(saved,visit.countryId))return <Screen><Title>Visit unavailable.</Title></Screen>;const safe=(action:(s:PreviewState)=>CityVisitsState,after:()=>void)=>{try{change(action);after();}catch(e){Alert.alert('City visit',(e as Error).message);}};return <NativeVisitDetails state={saved} now={now} id={visit.id} onCheckIn={()=>navigation.navigate('SpotCheckIn',{countryId:visit.countryId,visitId:visit.id})} onLeave={cancel=>safe(s=>leaveCityVisit(s,visit.id,cancel),()=>navigation.popTo('Visits'))} onBoard={countryId=>visit.spotId?navigation.navigate('SpotPeople',{countryId,spotId:visit.spotId}):navigation.navigate('SpotCheckIn',{countryId,visitId:visit.id})} onEdit={countryId=>navigation.navigate('PlanVisit',{countryId})}/>;}
function CityMeetPlanScreen({route,navigation}:NativeStackScreenProps<Root,'CityMeetPlan'>){const {saved,now}=useStore(),change=useVisitChange(),{countryId,visitorId}=route.params;if(!canUseCityBoard(saved,countryId))return <Screen><Title>Meetup unavailable.</Title></Screen>;return <NativeSpotMeetPlanner state={saved} now={now} countryId={countryId} visitorId={visitorId} onCheckIn={()=>navigation.navigate('SpotCheckIn',{countryId})} onPost={when=>{const result=change(s=>requestSpotMeet(s,countryId,visitorId,when));navigation.replace('CityMeetDetail',{id:result.meetings.filter(m=>m.visitorId===visitorId&&m.status==='pending').at(-1)!.id});}}/>;}
function CityMeetDetailScreen({route,navigation}:NativeStackScreenProps<Root,'CityMeetDetail'>){const {saved,now}=useStore(),change=useVisitChange(),m=saved.visits.meetings.find(m=>m.id===route.params.id);if(!m||!canUseCityBoard(saved,m.countryId))return <Screen><Title>Meetup unavailable.</Title></Screen>;const safe=(action:(s:PreviewState)=>CityVisitsState)=>{try{change(action);}catch(e){Alert.alert('Meetup',(e as Error).message);}};return <NativeCityMeetDetails state={saved} now={now} id={m.id} onAccept={()=>safe(s=>acceptCityMeetPreview(s,m.id))} onCancel={()=>safe(s=>cancelCityMeet(s,m.id))} onBoard={countryId=>navigation.navigate('CityBoard',{countryId})}/>;}
function CityUpdatesScreen(){const {saved,now}=useStore(),actions=useCommunityActions(),launch=useLaunchActions(),nav=useNavigation<Nav>(),openCheckIn=useCityMeetupOpen();if(saved.profile?.ageBand==='10-12')return <Screen><Title>Your private world.</Title></Screen>;if(saved.launch)return <NativeLaunchUpdates state={saved} onPalUpdate={actions.open} onCheckIn={()=>openCheckIn()} onInvite={()=>void launch.invite()} onTasks={()=>nav.navigate('Main',{screen:'Tasks'})} onCards={()=>nav.navigate('LaunchPostcards')}/>;return <NativePalUpdatesInbox state={saved} now={now} onRead={actions.readAll} onOpen={actions.open}/>;}

function usePhotoActions(){const {saved,setSaved}=useStore();return {change:(action:(s:PreviewState)=>CityPhotosState)=>setSaved(s=>({...s,photos:action(s)})),safe:(action:(s:PreviewState)=>CityPhotosState)=>{try{const photos=action(saved);setSaved(s=>({...s,photos}));}catch(e){Alert.alert('City photos',(e as Error).message);}}};}
function FavoritesScreen(){const {saved,now,setSaved}=useStore(),nav=useNavigation<Nav>();return <NativePlaceFeed header={<NativeSavedGuidePlaces/>} favorites state={saved} now={now} onCheckIn={()=>nav.navigate('Main',{screen:'Home'})} onFavorite={id=>setSaved(s=>togglePlaceFavorite(s,id))} onOpen={id=>nav.navigate('PlaceCheckInDetail',{id})}/>;}
function PalsScreen(){const {saved,setSaved,now}=useStore(),nav=useNavigation<Nav>(),play=usePlay();return <NativePlaceFeed header={<TravelWishlistBlock/>} state={saved} now={now} onPal={peerId=>nav.navigate('Pal',{peerId})} onPlay={play} onCheckIn={()=>nav.navigate('Camera')} onFavorite={id=>setSaved(s=>togglePlaceFavorite(s,id))} onOpen={id=>nav.navigate('PlaceCheckInDetail',{id})}/>;}
function PhotosScreen({route}:NativeStackScreenProps<Root,'CityPhotos'>){const {saved,setSaved,now}=useStore(),nav=useNavigation<Nav>(),countryId=route.params?.countryId;useEffect(()=>{if(countryId)setSaved(s=>markPlaceCheckInsSeen(s,countryId));},[countryId]);return <NativePlaceFeed state={saved} now={now} countryId={countryId} ownOnly={!countryId} onCheckIn={()=>nav.navigate('Camera')} onPal={peerId=>nav.navigate('Pal',{peerId})} onFavorite={id=>setSaved(s=>togglePlaceFavorite(s,id))} onOpen={id=>nav.navigate('PlaceCheckInDetail',{id})}/>;}
function CameraScreen({route}:NativeStackScreenProps<Root,'Camera'>){const {saved,setSaved,storage}=useStore(),nav=useNavigation<Nav>();return <NativeMapsPlaceShare key={(route.params?.peerId??'world')+(route.params?.sharedText??'paste')} recipient={palFor(saved,route.params?.peerId??'')?.alias} initialText={route.params?.sharedText} state={saved} onConfirm={async draft=>{const raw=await storage.getItem(KEY),current=raw?readPreview(JSON.parse(raw)):saved,next=route.params?.peerId?publishPlaceToPal(current,draft,route.params.peerId):publishMapsPlace(current,draft);try{await storage.setItem(KEY,JSON.stringify(next));}catch{throw new Error('Could not save your place. Please try again.');}setSaved(next);}} onHome={()=>route.params?.peerId?nav.popTo('Pal',{peerId:route.params.peerId}):nav.popTo('Main',{screen:'Home'})}/>;}
function PlaceCheckInDetailScreen({route}:NativeStackScreenProps<Root,'PlaceCheckInDetail'>){const {saved,setSaved,now}=useStore(),nav=useNavigation<Nav>();return <NativePlaceDetail onShare={saved.profile?.ageBand==='10-12'?undefined:place=>{void shareGem(place);}} state={saved} now={now} id={route.params.id} onFavorite={id=>setSaved(s=>togglePlaceFavorite(s,id))} onCheckIn={()=>nav.navigate('Camera')} onPal={peerId=>nav.navigate('Pal',{peerId})}/>;}

function useCommunityActions(){const {saved,setSaved}=useStore(),nav=useNavigation<Nav>();return {readAll:()=>setSaved(s=>readPalUpdates(s)),open:(note:PalUpdate)=>{const current=palUpdates(saved).find(n=>n.id===note.id);if(!current)return;setSaved(s=>readPalUpdates(s,[current.id]));if(current.target==='pal'&&current.peerId)nav.navigate('Pal',{peerId:current.peerId});else if(current.target==='pal-meet'&&current.peerId)nav.navigate('PalMeeting',{peerId:current.peerId});else if(current.target==='photos'){if(current.photoId)nav.navigate('PlaceCheckInDetail',{id:current.photoId});else nav.navigate('CityPhotos',{countryId:current.countryId});}else nav.navigate('CityBoard',{countryId:current.countryId});}};}
function SpotCheckInScreen({route,navigation}:NativeStackScreenProps<Root,'SpotCheckIn'>){const {saved,now}=useStore(),change=useVisitChange(),{countryId,visitId}=route.params;if(!canUseCityBoard(saved,countryId))return <Screen><Title>Discover this city first.</Title></Screen>;return <NativeSpotCheckIn state={saved} now={now} id={countryId} onCheckIn={spotId=>{change(s=>checkInAtSpot(s,countryId,spotId,new Date(),visitId));navigation.replace('SpotPeople',{countryId,spotId});}}/>;}
function SpotPeopleScreen({route,navigation}:NativeStackScreenProps<Root,'SpotPeople'>){const {saved,now}=useStore(),change=useVisitChange(),{countryId,spotId}=route.params;if(!canUseCityBoard(saved,countryId)||!citySpot(countryId,spotId))return <Screen><Title>Spot unavailable.</Title></Screen>;return <NativeSpotPeople state={saved} now={now} id={countryId} spotId={spotId} onMeet={visitorId=>navigation.navigate('CityMeetPlan',{countryId,visitorId})} onLeave={()=>{try{change(s=>leaveCityVisit(s,currentCityVisit(s,countryId)!.id));}catch(e){Alert.alert('Check out',(e as Error).message);}}} onChange={()=>navigation.replace('SpotCheckIn',{countryId})} onCheckIn={()=>navigation.replace('SpotCheckIn',{countryId})}/>;}

function PalScreen({route}:NativeStackScreenProps<Root,'Pal'>){const {saved,setSaved,now,setSetup}=useStore(),nav=useNavigation<Nav>(),play=usePlay(),openCheckIn=useCityMeetupOpen(),change=useSocialChange(),photos=usePhotoActions(),id=route.params.peerId,p=palFor(saved,id);if(!p)return <Screen><Title>Roamie unavailable.</Title></Screen>;return <NativePalDetail onFavorite={id=>setSaved(s=>togglePlaceFavorite(s,id))} state={saved} now={now} id={id} onPlay={()=>saved.launch?play(id):hasDailyProgress(saved.daily)?play():nav.navigate('Categories',{peerId:id})} onPhotos={(countryId,photoId)=>photoId?nav.navigate('PlaceCheckInDetail',{id:photoId}):nav.navigate('CityPhotos',{countryId})} onCity={countryId=>nav.navigate('Country',{countryId})} onChat={()=>{setSaved(s=>markPalDMRead(s,id));nav.navigate('PalChat',{peerId:id});}} onPlan={countryId=>saved.launch?openCheckIn(countryId):nav.navigate('PlanVisit',{countryId})} onMeet={()=>nav.navigate('PalMeeting',{peerId:id})} onEditProfile={()=>{setSetup(createSetupProfile(saved.profile!));nav.navigate('Setup');}}/>;}
function PalChatScreen({route}:NativeStackScreenProps<Root,'PalChat'>){const {saved,setSaved}=useStore(),nav=useNavigation<Nav>(),id=route.params.peerId,focused=useIsFocused(),pal=palFor(saved,id),last=palDMMessages(saved,id).at(-1)?.id;useEffect(()=>{if(focused&&pal)setSaved(s=>markPalDMRead(s,id));},[id,focused,last,!!pal]);if(!pal)return <Screen><Title>Roamie unavailable.</Title></Screen>;return <NativePalDM state={saved} id={id} onSend={body=>setSaved(s=>sendPalDM(s,id,body))} onPal={()=>nav.navigate('Pal',{peerId:id})} onMeet={()=>nav.navigate('PalMeeting',{peerId:id})}/>;}

function PalMeetingScreen({route}:NativeStackScreenProps<Root,'PalMeeting'>){const {saved,now}=useStore(),change=useSocialChange(),visits=useVisitChange(),id=route.params.peerId,p=palFor(saved,id);if(!p||!isAdult(saved.profile!.ageBand))return <Screen><Title>Meeting unavailable.</Title></Screen>;return <NativePalMeeting state={saved} now={now} id={id} onCheckIn={spot=>visits(s=>checkInAtSpot(s,p.countryId,spot))} onShare={(spot,when)=>change(s=>sharePalMeeting(s,id,spot,meetingDateTime(when.split('T')[0],when.split('T')[1],countryById(p.countryId)!.timeZone)))} onRespond={(plan,accept)=>change(s=>respondPalMeeting(s,plan,accept))}/>;}


function useLaunchActions(){
 const {saved,setSaved,storage}=useStore(),nav=useNavigation<Nav>(),play=usePlay(),lock=useRef(false);
 async function change(action:(s:PreviewState)=>PreviewState){const next=seedGlobalPals(action(saved));try{await storage.setItem(KEY,JSON.stringify(next));}catch{throw new Error('Couldn’t save. Remove an older photo or free some device storage.');}setSaved(next);return next;}
 async function safe(action:(s:PreviewState)=>PreviewState){if(lock.current)return;lock.current=true;try{await change(action);}catch(e){Alert.alert('Your passport',(e as Error).message);}finally{lock.current=false;}}
 async function invite(){if(lock.current)return;if(saved.profile?.ageBand==='10-12'){nav.navigate('Main',{screen:'Cities'});return;}if(!hasDayCard(saved)){await prepare();return;}lock.current=true;try{const invite=await makeFriendInvite(saved,nativeChallengeCrypto);await change(s=>rememberInvite(s,invite));nav.navigate('LaunchInvite',{inviteId:invite.id});}catch(e){Alert.alert('Friend challenge',(e as Error).message);}finally{lock.current=false;}}
 async function prepare(){if(lock.current)return;lock.current=true;try{const next=await change(s=>beginDayCard(s));nav.navigate('Play',{index:invitePreparationIndex(next),invite:true});}catch(e){Alert.alert('Your invite',(e as Error).message);}finally{lock.current=false;}}
 return {change,safe,invite,prepare};
}
function LaunchReadyScreen(){const {saved}=useStore(),nav=useNavigation<Nav>(),launch=useLaunchActions();return <NativeLaunchReady state={saved} onInvite={()=>void launch.invite()} onGuide={()=>nav.navigate('Main',{screen:'Cities'})}/>;}
function LaunchInviteScreen(props:NativeStackScreenProps<Root,'LaunchInvite'>){return <NativeHeaderUnderlay><LaunchInviteContent {...props}/></NativeHeaderUnderlay>;}
function LaunchInviteContent({route}:NativeStackScreenProps<Root,'LaunchInvite'>){const {saved}=useStore(),nav=useNavigation<Nav>(),invite=saved.launch?.invites.find(i=>i.id===route.params.inviteId);return invite?<NativeLaunchInvite state={saved} invite={invite} onBack={()=>nav.popTo('Main',{screen:'Home'})}/>:<Screen><Title>Start with your 3.</Title></Screen>;}
function LaunchReceiverScreen({route}:NativeStackScreenProps<Root,'LaunchReceiver'>){const {saved}=useStore(),nav=useNavigation<Nav>(),launch=useLaunchActions(),invite=saved.launch?.invites.find(i=>i.id===route.params.inviteId);if(!invite||!saved.profile||saved.profile.ageBand==='10-12')return <Screen><Title>Start with your day card.</Title></Screen>;return <NativeDayCardReceiver key={invite.id} state={saved} invite={invite} onComplete={async reply=>{await launch.change(s=>collectPostcard(s,reply));}} onReturn={()=>nav.reset(palFindingProgress(saved).unlocked?{index:0,routes:[{name:'Main',params:{screen:'Home'}}]}:{index:1,routes:[{name:'Main',params:{screen:'Home'}},{name:'Profile'}]})}/>;}
function LaunchGuideScreen(props:NativeStackScreenProps<Root,'Guide'>){return <NativeHeaderUnderlay><LaunchGuideContent {...props}/></NativeHeaderUnderlay>;}
function LaunchGuideContent({route}:NativeStackScreenProps<Root,'Guide'>){const {saved}=useStore(),launch=useLaunchActions(),openCheckIn=useCityMeetupOpen(),id=route.params.countryId;return <NativeLaunchGuide key={id} state={saved} onCheckIn={()=>openCheckIn(id)} id={id} onSave={()=>void launch.safe(s=>toggleGuide(s,id))} onPlace={place=>void launch.safe(s=>toggleGuidePlace(s,place))}/>;}
function LaunchPostcardsScreen({route}:NativeStackScreenProps<Root,'LaunchPostcards'>){const {saved}=useStore(),launch=useLaunchActions(),nav=useNavigation<Nav>();return <NativeLaunchPostcards initialImport={!!route.params?.import} state={saved} onPlay={()=>void launch.invite()} onCollect={async reply=>{await launch.change(s=>collectPostcard(s,reply));nav.navigate('LaunchUnlock');}}/>;}
function LaunchMomentsScreen(){const {saved,setSaved,now}=useStore(),nav=useNavigation<Nav>();return <NativePlaceFeed ownOnly state={saved} now={now} onCheckIn={()=>nav.navigate('Camera')} onFavorite={id=>setSaved(s=>togglePlaceFavorite(s,id))} onOpen={id=>nav.navigate('PlaceCheckInDetail',{id})}/>;}
function LaunchUnlockScreen({route}:NativeStackScreenProps<Root,'LaunchUnlock'>){const {saved,now}=useStore(),nav=useNavigation<Nav>(),launch=useLaunchActions(),play=usePlay();return <NativeLaunchUnlock allowSimulation={palFindingProgress(saved).canPlay} state={saved} now={now} autoPreview={!!route.params?.demo} onSimulate={async()=>{await launch.change(s=>simulatePalUnlock(s));}} onResetPreview={async()=>{await launch.change(resetPalUnlock);nav.popTo('Main',{screen:'Home'});}} onPrepare={()=>void launch.prepare()} onInvite={()=>void launch.invite()} onPlay={play} onExplore={()=>nav.navigate('Main',{screen:'Cities'})} onImport={()=>nav.navigate('LaunchPostcards',{import:true})}/>;}

function useCityMeetupOpen(){const {saved,setSaved}=useStore(),nav=useNavigation<Nav>();return (countryId?:CountryId)=>{if(saved.cityMeetup?.checkIn)setSaved(s=>({...s,cityMeetup:s.cityMeetup?viewMeetupRequests(s.cityMeetup):undefined}));nav.navigate('CityCheckIn',{countryId});};}
function CityCheckInScreen({route,navigation}:NativeStackScreenProps<Root,'CityCheckIn'>){const {saved,now}=useStore(),launch=useLaunchActions();if(!saved.profile||saved.profile.ageBand==='10-12')return <Screen><Title>Your private world.</Title></Screen>;return <NativeCityMeetupFlow profile={saved.profile} session={saved.cityMeetup} now={now} initialCity={route.params?.countryId} onChange={async next=>{await launch.change(s=>({...s,cityMeetup:next}));}} onExit={()=>navigation.popTo('Main',{screen:'Cities'})}/>;}

function PalVisitMeetScreen({route,navigation}:NativeStackScreenProps<Root,'PalVisitMeet'>){const {saved,now}=useStore(),launch=useLaunchActions();return <NativeHomeVisitMeet state={saved} now={now} peerId={route.params.peerId} onChange={async action=>{await launch.change(action);}} onBack={()=>navigation.popTo('Main',{screen:'Home'})}/>;}
